//! The generator: provider files in, every table and doc out.
//!
//! [`render`] returns every generated file (path relative to the repository
//! root, contents), [`write`] writes them and [`check`] compares them with
//! the tree. The gate is a test (`tests/generated.rs`) as well as the binary's
//! `--check`, so a stale file fails `cargo nextest` and the pre-push script.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use crate::schema::{ProviderDef, load_dir};
use crate::{ENDPOINT_HARNESSES, HARNESS_IDS, MethodKind};

/// Where the provider files live, relative to the repository root.
pub const PROVIDERS_DIR: &str = "libs/cua/crates/cua-connections/providers";
/// The generated Rust tables.
pub const RUST_OUT: &str = "libs/cua/crates/cua-connections/src/generated.rs";
/// The registry as JSON: the parity data the web and SwiftUI apps test against.
pub const JSON_OUT: &str = "libs/cua/crates/cua-connections/generated/providers.json";
/// The web app's copy (ids, names, icons, tiers, aliases).
pub const TS_OUT: &str = "apps/cua-spaces-web/src/bridge/generated/providers.ts";
/// The SwiftUI app's copy.
pub const SWIFT_OUT: &str =
    "apps/cua-spaces-macos/Sources/CuaSpacesMacKit/Models/ProviderRegistry.generated.swift";
/// The docs page that carries the generated provider table.
pub const DOCS_PAGE: &str = "docs/content/docs/spaces/guides/connections.mdx";
/// The markers around the generated table in [`DOCS_PAGE`].
pub const DOCS_START: &str = "{/* providers:start (generated by cua-connections-gen) */}";
pub const DOCS_END: &str = "{/* providers:end */}";

/// The repository root, from this crate's manifest directory.
pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../../..")
        .canonicalize()
        .expect("the crate sits in the repository")
}

const RUST_HEADER: &str = "// Generated by `cargo run -p cua-connections --bin cua-connections-gen` from\n\
// providers/*.toml. Do not edit: change a provider file and run the generator.\n\
// `--check` (and tests/generated.rs) fail when this file is stale.\n\n";

fn s(x: &str) -> String {
    format!("{x:?}")
}

fn list(items: &[String]) -> String {
    if items.is_empty() {
        "&[]".into()
    } else {
        format!("&[{}]", items.iter().map(|i| s(i)).collect::<Vec<_>>().join(", "))
    }
}

fn const_name(harness: &str) -> String {
    format!("READS_{}", harness.replace('-', "_").to_ascii_uppercase())
}

/// The names `harness` reads, in rank order, from the visible providers.
fn reads(all: &[ProviderDef], harness: &str) -> Vec<String> {
    let mut v: Vec<String> = vec![];
    for p in all.iter().filter(|p| !p.hidden && !p.terms_review()) {
        if let Some(entries) = p.delivery.get(harness) {
            for raw in entries {
                let (dest, _) = ProviderDef::entry(raw);
                if !v.iter().any(|x| x == dest) {
                    v.push(dest.to_string());
                }
            }
        }
    }
    v
}

fn rust(all: &[ProviderDef]) -> String {
    let mut o = String::from(RUST_HEADER);
    o.push_str("use crate::{Check, Delivery, Entry, Field, Kind, Method, MethodKind, Provider, Region, Tier};\n\n");
    o.push_str("/// Every provider, in rank order (hidden ones included).\n");
    o.push_str("pub static PROVIDERS: &[Provider] = &[\n");
    for p in all {
        o.push_str("    Provider {\n");
        o.push_str(&format!("        id: {},\n", s(&p.id)));
        o.push_str(&format!("        name: {},\n", s(&p.name)));
        let icon = if p.icon.is_empty() { &p.id } else { &p.icon };
        o.push_str(&format!("        icon: {},\n", s(icon)));
        o.push_str(&format!("        tier: Tier::{},\n", if p.tier == "top" { "Top" } else { "More" }));
        o.push_str(&format!("        rank: {},\n", p.rank));
        let kind = match p.kind.as_str() {
            "hosted" => "Hosted",
            "aggregator" => "Aggregator",
            "local" => "Local",
            "custom" => "Custom",
            _ => "Cloud",
        };
        o.push_str(&format!("        kind: Kind::{kind},\n"));
        o.push_str(&format!("        hidden: {},\n", p.hidden));
        o.push_str(&format!("        hidden_reason: {},\n", s(&p.hidden_reason)));
        o.push_str(&format!("        terms_review: {},\n", p.terms_review()));
        o.push_str(&format!("        aliases: {},\n", list(&p.aliases)));
        o.push_str(&format!("        wire: {},\n", s(&p.wire)));
        o.push_str(&format!("        also_wires: {},\n", list(&p.also_wires)));
        o.push_str(&format!("        base_url: {},\n", s(&p.base_url)));
        o.push_str(&format!("        base_url_env: {},\n", s(&p.base_url_env)));
        o.push_str(&format!("        default_model: {},\n", s(&p.default_model)));
        o.push_str(&format!("        hermes_id: {},\n", s(&p.hermes_id)));
        o.push_str(&format!("        key_help: {},\n", s(&p.key_help)));
        o.push_str(&format!("        placeholder: {},\n", s(&p.placeholder)));
        match &p.check {
            Some(c) => o.push_str(&format!(
                "        check: Some(Check {{ path: {}, auth: {} }}),\n",
                s(&c.path),
                s(&c.auth)
            )),
            None => o.push_str("        check: None,\n"),
        }
        o.push_str(&format!("        apps: {},\n", list(&p.apps)));
        o.push_str("        methods: &[\n");
        for m in &p.method {
            let kind = MethodKind::parse(&m.kind).expect("checked");
            let kind = format!("{kind:?}");
            o.push_str("            Method {\n");
            o.push_str(&format!("                id: {},\n", s(&m.id)));
            o.push_str(&format!("                kind: MethodKind::{kind},\n"));
            o.push_str(&format!("                env: {},\n", s(&m.env)));
            o.push_str(&format!("                aliases: {},\n", list(&m.aliases)));
            o.push_str(&format!("                scope: {},\n", s(&m.scope)));
            o.push_str(&format!("                app: {},\n", s(&m.app)));
            o.push_str(&format!("                flow: {},\n", s(&m.flow)));
            o.push_str(&format!("                label: {},\n", s(&m.label)));
            o.push_str(&format!("                help: {},\n", s(&m.help)));
            o.push_str(&format!("                terms_review: {},\n", m.terms == "review"));
            o.push_str(&format!("                secret_optional: {},\n", m.secret == "optional"));
            o.push_str("                fields: &[\n");
            for f in &m.field {
                o.push_str(&format!(
                    "                    Field {{ id: {}, label: {}, kind: {}, placeholder: {}, required: {}, options: {} }},\n",
                    s(&f.id),
                    s(&f.label),
                    s(&f.kind),
                    s(&f.placeholder),
                    f.required,
                    list(&f.options)
                ));
            }
            o.push_str("                ],\n            },\n");
        }
        o.push_str("        ],\n        regions: &[\n");
        for r in &p.region {
            o.push_str(&format!(
                "            Region {{ id: {}, name: {}, base_url: {} }},\n",
                s(&r.id),
                s(&r.name),
                s(&r.base_url)
            ));
        }
        o.push_str("        ],\n        delivery: &[\n");
        for (h, entries) in &p.delivery {
            o.push_str(&format!("            Delivery {{ harness: {}, entries: &[", s(h)));
            for raw in entries {
                let (d, src) = ProviderDef::entry(raw);
                o.push_str(&format!("Entry {{ dest: {}, src: {} }}, ", s(d), s(src)));
            }
            o.push_str("] },\n");
        }
        o.push_str("        ],\n    },\n");
    }
    o.push_str("];\n\n");
    o.push_str("/// The names each app reads from saved connections, in rank order (visible providers).\n");
    for h in HARNESS_IDS {
        o.push_str(&format!(
            "pub const {}: &[&str] = {};\n",
            const_name(h),
            list(&reads(all, h))
        ));
    }
    o.push_str("\n/// [`READS_*`](READS_CLAUDE_CODE) by harness id.\npub const READS: &[(&str, &[&str])] = &[\n");
    for h in HARNESS_IDS {
        o.push_str(&format!("    ({}, {}),\n", s(h), const_name(h)));
    }
    o.push_str("];\n\n");
    let ids: Vec<String> = all.iter().filter(|p| !p.hidden && !p.terms_review()).map(|p| p.id.clone()).collect();
    o.push_str("/// The ids `cua connections add` takes (visible providers).\n");
    o.push_str(&format!("pub const PROVIDER_IDS: &[&str] = {};\n\n", list(&ids)));
    o.push_str("/// The text under `cua connections add --help`.\n");
    o.push_str(&format!("pub const CLI_PROVIDER_HELP: &str = {};\n", s(&cli_help(all))));
    o
}

/// The provider list for `cua connections add --help`.
pub fn cli_help(all: &[ProviderDef]) -> String {
    let mut o = String::from("Providers:\n");
    let vis: Vec<&ProviderDef> = all.iter().filter(|p| !p.hidden && !p.terms_review()).collect();
    let w = vis.iter().map(|p| p.id.len()).max().unwrap_or(0);
    for p in &vis {
        o.push_str(&format!("  {:<w$}  {}\n", p.id, p.name));
    }
    o.push_str("\nMethods: key (an API key read from stdin), import (the sign-in another app made on this machine), login (a code sign-in), endpoint (a base URL).\n");
    o
}

fn json(all: &[ProviderDef]) -> String {
    let rows: Vec<serde_json::Value> = all
        .iter()
        .map(|p| {
            serde_json::json!({
                "id": p.id,
                "name": p.name,
                "icon": if p.icon.is_empty() { &p.id } else { &p.icon },
                "tier": p.tier,
                "rank": p.rank,
                "kind": p.kind,
                "hidden": p.hidden || p.terms_review(),
                "aliases": p.aliases,
                "wire": p.wire,
                "alsoWires": p.also_wires,
                "hermesId": p.hermes_id,
                "regions": p.region.iter().map(|r| r.id.clone()).collect::<Vec<_>>(),
                "methods": p.method.iter().filter(|m| m.terms != "review").map(|m| serde_json::json!({
                    "id": m.id, "kind": m.kind, "scope": m.scope,
                })).collect::<Vec<_>>(),
                "delivery": p.delivery.iter().map(|(h, e)| (h.clone(), serde_json::json!(e))).collect::<serde_json::Map<_, _>>(),
            })
        })
        .collect();
    let mut t = serde_json::to_string_pretty(&serde_json::json!({
        "harnesses": HARNESS_IDS,
        "methodKinds": MethodKind::ALL.iter().map(|k| k.word()).collect::<Vec<_>>(),
        "providers": rows,
    }))
    .expect("json");
    t.push('\n');
    t
}

fn ts(all: &[ProviderDef]) -> String {
    let mut o = String::from(
        "// SPDX-License-Identifier: FSL-1.1-MIT\n// Copyright (c) 2026 Cua AI, Inc.\n\n\
         // Generated by `cargo run -p cua-connections --bin cua-connections-gen` from\n\
         // libs/cua/crates/cua-connections/providers/*.toml. Do not edit.\n\n",
    );
    o.push_str("export interface ProviderEntry {\n  id: string;\n  name: string;\n  icon: string;\n  tier: \"top\" | \"more\";\n  aliases: string[];\n  /** The variable a key for it is saved as. */\n  keyEnv: string;\n}\n\n");
    o.push_str("/** The providers a person can see, in rank order. */\nexport const PROVIDER_REGISTRY: ProviderEntry[] = [\n");
    for p in all.iter().filter(|p| !p.hidden && !p.terms_review()) {
        let icon = if p.icon.is_empty() { &p.id } else { &p.icon };
        let key_env = p
            .method
            .iter()
            .find(|m| matches!(m.kind.as_str(), "api_key" | "custom_endpoint"))
            .map(|m| m.env.as_str())
            .unwrap_or_default();
        o.push_str(&format!(
            "  {{ id: {}, name: {}, icon: {}, tier: {}, aliases: {}, keyEnv: {} }},\n",
            s(&p.id),
            s(&p.name),
            s(icon),
            s(&p.tier),
            serde_json::to_string(&p.aliases).expect("json").replace(',', ", "),
            s(key_env)
        ));
    }
    o.push_str("];\n\n/** The kinds of way to connect a provider (a closed set). */\nexport const METHOD_KINDS = [");
    o.push_str(
        &MethodKind::ALL
            .iter()
            .map(|k| s(k.word()))
            .collect::<Vec<_>>()
            .join(", "),
    );
    o.push_str("] as const;\n");
    o
}

fn swift(all: &[ProviderDef]) -> String {
    let mut o = String::from(
        "// SPDX-License-Identifier: FSL-1.1-MIT\n// Copyright (c) 2026 Cua AI, Inc.\n\n\
         // Generated by `cargo run -p cua-connections --bin cua-connections-gen` from\n\
         // libs/cua/crates/cua-connections/providers/*.toml. Do not edit.\n\n\
         /// The providers a person can see, in rank order, as the app core lists them.\n\
         public enum ProviderRegistry {\n    public static let ids: [String] = [\n",
    );
    for p in all.iter().filter(|p| !p.hidden && !p.terms_review()) {
        o.push_str(&format!("        {},\n", s(&p.id)));
    }
    o.push_str("    ]\n\n    public static let methodKinds: [String] = [\n");
    for k in MethodKind::ALL {
        o.push_str(&format!("        {},\n", s(k.word())));
    }
    o.push_str("    ]\n}\n");
    o
}

/// The provider table for the docs page (prose page, one table).
pub fn docs_table(all: &[ProviderDef]) -> String {
    let mut o = String::from("| Provider | How to connect | Works with |\n| --- | --- | --- |\n");
    for p in all.iter().filter(|p| !p.hidden && !p.terms_review()) {
        let how: Vec<&str> = p
            .method
            .iter()
            .filter(|m| m.terms != "review")
            .map(|m| match m.kind.as_str() {
                "api_key" => "API key",
                "import_login" => "Your sign-in on this machine",
                "device_code" | "subscription_login" => "Plan sign-in",
                "browser_oauth" => "Browser sign-in",
                "adc" => "Cloud credentials",
                "local_server" => "Server URL",
                _ => "Base URL and key",
            })
            .collect();
        let works = works_with_names(p, all);
        o.push_str(&format!("| {} | {} | {} |\n", p.name, how.join(", "), works.join(", ")));
    }
    o
}

fn harness_name(id: &str) -> &'static str {
    match id {
        "claude-code" => "Claude Code",
        "openai-codex" => "Codex",
        "gemini-cli" => "Gemini CLI",
        "google-antigravity" => "Antigravity",
        "opencode" => "OpenCode",
        "goose" => "Goose",
        "pi" => "Pi",
        "hermes" => "Hermes",
        "openclaw" => "OpenClaw",
        _ => "",
    }
}

fn app_name(id: &str) -> &'static str {
    match id {
        "copilot-cli" => "GitHub Copilot CLI",
        "t3code" => "T3 Code",
        _ => "",
    }
}

/// The same chips the app shows, for the docs (computed from the definition:
/// delivery entries, then the endpoint apps whose wire the provider serves).
fn works_with_names(p: &ProviderDef, _all: &[ProviderDef]) -> Vec<String> {
    let mut v: Vec<String> = vec![];
    for h in HARNESS_IDS {
        let native = p.delivery.get(*h).is_some_and(|e| !e.is_empty());
        let has_any = p.delivery.contains_key(*h);
        let wire = ENDPOINT_HARNESSES.iter().find(|(x, _)| x == h).map(|(_, w)| *w);
        let overlap = wire.is_some_and(|w| p.wire == w || p.also_wires.iter().any(|a| a == w))
            && (p.kind == "custom" || (!p.base_url.is_empty() && !p.default_model.is_empty()));
        if native || (!has_any && overlap) {
            v.push(harness_name(h).to_string());
        }
    }
    for a in &p.apps {
        v.push(app_name(a).to_string());
    }
    v
}

/// Replaces the generated region of the docs page with `table`.
pub fn splice_docs(page: &str, table: &str) -> Result<String, String> {
    let a = page
        .find(DOCS_START)
        .ok_or_else(|| format!("{DOCS_PAGE} lacks the {DOCS_START} marker"))?;
    let b = page
        .find(DOCS_END)
        .ok_or_else(|| format!("{DOCS_PAGE} lacks the {DOCS_END} marker"))?;
    if b < a {
        return Err("the docs markers are in the wrong order".into());
    }
    Ok(format!(
        "{}{}\n\n{}\n{}{}",
        &page[..a],
        DOCS_START,
        table,
        DOCS_END,
        &page[b + DOCS_END.len()..]
    ))
}

/// Every generated file for the files under `root`.
pub fn render(root: &Path) -> Result<BTreeMap<String, String>, String> {
    let all = load_dir(&root.join(PROVIDERS_DIR))?;
    let mut out = BTreeMap::new();
    out.insert(RUST_OUT.to_string(), rust(&all));
    out.insert(JSON_OUT.to_string(), json(&all));
    out.insert(TS_OUT.to_string(), ts(&all));
    out.insert(SWIFT_OUT.to_string(), swift(&all));
    let page = std::fs::read_to_string(root.join(DOCS_PAGE))
        .map_err(|e| format!("{DOCS_PAGE}: {e}"))?;
    out.insert(DOCS_PAGE.to_string(), splice_docs(&page, &docs_table(&all))?);
    Ok(out)
}

/// Writes the generated files under `root`.
pub fn write(root: &Path) -> Result<Vec<String>, String> {
    let files = render(root)?;
    let mut changed = vec![];
    for (rel, text) in files {
        let path = root.join(&rel);
        if std::fs::read_to_string(&path).ok().as_deref() == Some(text.as_str()) {
            continue;
        }
        if let Some(dir) = path.parent() {
            std::fs::create_dir_all(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
        }
        std::fs::write(&path, text).map_err(|e| format!("{rel}: {e}"))?;
        changed.push(rel);
    }
    Ok(changed)
}

/// The generated files that differ from the tree (empty: current).
pub fn check(root: &Path) -> Result<Vec<String>, String> {
    let files = render(root)?;
    Ok(files
        .into_iter()
        .filter(|(rel, text)| std::fs::read_to_string(root.join(rel)).ok().as_deref() != Some(text.as_str()))
        .map(|(rel, _)| rel)
        .collect())
}
